// ==UserScript==
// @name         Goffy Gober Shell Eater - Goose Mod
// @namespace    https://github.com/override909/goffy-gober-shell-eater-mod
// @version      0.4.0
// @description  Cosmetic only: eggs wearing the turkey face become an Untitled-Goose-Game-style goose, turkey gun skins become goose guns, grenades become Fall Guys ducks with a vine-boom explosion. Toggle in the Goose Mod settings (Alt+G).
// @match        *://shellshock.io/*
// @match        *://*.shellshock.io/*
// @match        *://*.shellshockers.*/*
// @run-at       document-start
// @grant        none
// ==/UserScript==

/*
 * - Purely visual and only on YOUR screen. It changes how already-drawn eggs/guns look;
 *   it reads nothing else about other players and sends nothing anywhere.
 * - Finding "the turkey face" and "turkey gun skins" is a best-effort name match on the
 *   game's meshes/materials. The game's internal names change between updates, so you
 *   may need to tweak CONFIG.facePattern / CONFIG.gunWords. Turn on "Debug log" in the
 *   settings panel and check the browser console (F12).
 */
(function () {
  'use strict';

  // ---------------------------------------------------------------------------------
  // CONFIG: advanced tweaks (edit here). Everyday on/off switches live in the panel.
  // ---------------------------------------------------------------------------------
  const CONFIG = {
    facePattern: /turkey/i,      // the turkey face item
    gunWords: /(gun|weapon|eggk|scrambler|ranger|rpegg|whipper|crackshot|trihard|cluck|pistol|smg|shotgun|sniper|rocket)/i,
    // Untitled Goose Game palette (body, feet, beak, eyes)
    gooseColors: { body: '#f4f2ec', feet: '#f0912f', beak: '#f0912f', eyes: '#1b1b1b' },
    gooseScale: 1.0,
    gooseOffset: { x: 0, y: 0, z: 0 },
    gooseRotationY: 0,           // radians; use Math.PI if the goose faces backwards
    gunScale: 1.0,
    gunRotation: { x: 0, y: 0, z: 0 },
    grenadePattern: /grenade/i,  // any grenade (independent of skins)
    grenadeScale: 1.0,           // 1 = duck as tall as ~1.4x the grenade
    // sound files to replace with the vine boom (matched against the file URL)
    grenadeSoundPattern: /(grenade|explo|boom)[^/]*\.(mp3|ogg|wav|m4a|webm|aac)(\?|#|$)/i,
    maxPlayerMeshes: 40,         // safety: never hide a node tree bigger than this
    scanIntervalMs: 500,
  };

  // ---------------------------------------------------------------------------------
  // Settings (toggled in the in-game panel, saved in this browser only)
  // ---------------------------------------------------------------------------------
  const SETTINGS_KEY = 'goffyGooseMod.settings';
  const DEFAULTS = { enabled: true, gooseSkin: true, gooseGuns: true, duckGrenades: true, grenadeSound: true, model: 'detailed', debug: false };
  const settings = Object.assign({}, DEFAULTS, load());
  function load() { try { return JSON.parse(localStorage.getItem(SETTINGS_KEY)) || {}; } catch (e) { return {}; } }
  function save() { try { localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings)); } catch (e) { /* private mode etc. */ } }

  const log = (...a) => settings.debug && console.log('[GooseMod]', ...a);

  // ---------------------------------------------------------------------------------
  // Grenade sound -> vine boom. The game's sound files are swapped at download time,
  // so this has to be installed before the game loads (it is: document-start).
  // Changing this toggle needs a page reload.
  // ---------------------------------------------------------------------------------
  function installSoundSwap() {
    if (!settings.enabled || !settings.grenadeSound) return;
    let boomUrl = null;
    const boom = () => {
      if (!boomUrl && BOOM_MP3) boomUrl = URL.createObjectURL(new Blob([b64(BOOM_MP3, Uint8Array)], { type: 'audio/mpeg' }));
      return boomUrl;
    };
    const swap = (url) => {
      const u = String(url);
      if (!CONFIG.grenadeSoundPattern.test(u) || !boom()) return url;
      log('sound swapped:', u);
      return boom();
    };
    const xhrOpen = XMLHttpRequest.prototype.open;
    XMLHttpRequest.prototype.open = function (method, url, ...rest) { return xhrOpen.call(this, method, swap(url), ...rest); };
    const origFetch = window.fetch;
    window.fetch = function (input, init) {
      if (typeof input === 'string' || input instanceof URL) input = swap(input);
      else if (input && input.url && swap(input.url) !== input.url) input = swap(input.url);
      return origFetch.call(this, input, init);
    };
    const srcDesc = Object.getOwnPropertyDescriptor(HTMLMediaElement.prototype, 'src');
    Object.defineProperty(HTMLMediaElement.prototype, 'src', {
      configurable: true, enumerable: srcDesc.enumerable,
      get() { return srcDesc.get.call(this); },
      set(v) { srcDesc.set.call(this, swap(v)); },
    });
  }

  // ---------------------------------------------------------------------------------
  // Embedded goose model (generated by tools/build-model.mjs; do not edit by hand)
  // ---------------------------------------------------------------------------------
  const MODEL = /* MODEL_DATA_START */ {"extent":[0.30434,1.35,0.5158],"pos":"","idx":"","slot":""} /* MODEL_DATA_END */;
  const GRENADE = /* GRENADE_DATA_START */ {"extent":[0.55133,1,0.49243],"pos":"","idx":"","rgb":""} /* GRENADE_DATA_END */;
  const BOOM_MP3 = /* SOUND_DATA_START */ '' /* SOUND_DATA_END */;
  const SLOTS = ['body', 'feet', 'beak', 'eyes'];

  function b64(s, Type) {
    const bin = atob(s); const u8 = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
    return new Type(u8.buffer);
  }

  function gooseMaterial(B, scene, name) {
    // soft, matte, slightly self-lit = the flat pastel look of Untitled Goose Game
    const m = new B.StandardMaterial(name, scene);
    m.diffuseColor = new B.Color3(1, 1, 1);
    m.specularColor = new B.Color3(0, 0, 0);
    m.emissiveColor = new B.Color3(0.28, 0.28, 0.28);
    return m;
  }

  // Builds a mesh from embedded data: colours come either from colour slots
  // (goose -> CONFIG.gooseColors) or from baked per-vertex RGB (duck grenade).
  function buildEmbedded(B, scene, data, name) {
    const q = b64(data.pos, Int16Array), idx = b64(data.idx, Uint16Array);
    const slots = data.slot && b64(data.slot, Uint8Array), rgb = data.rgb && b64(data.rgb, Uint8Array);
    const n = q.length / 3, positions = new Float32Array(n * 3), colors = new Float32Array(n * 4);
    const pal = SLOTS.map((s) => B.Color3.FromHexString(CONFIG.gooseColors[s]));
    for (let i = 0; i < n; i++) {
      for (let k = 0; k < 3; k++) positions[i * 3 + k] = (q[i * 3 + k] / 32767) * data.extent[k];
      if (rgb) colors.set([rgb[i * 3] / 255, rgb[i * 3 + 1] / 255, rgb[i * 3 + 2] / 255, 1], i * 4);
      else { const c = pal[slots[i]] || pal[0]; colors.set([c.r, c.g, c.b, 1], i * 4); }
    }
    const normals = [];
    B.VertexData.ComputeNormals(positions, idx, normals);
    const vd = new B.VertexData();
    Object.assign(vd, { positions, indices: idx, colors, normals });
    const mesh = new B.Mesh(name, scene);
    vd.applyToMesh(mesh, false);
    mesh.material = gooseMaterial(B, scene, name + '_mat');
    return mesh;
  }

  // Simple duck (used if the embedded grenade model is missing).
  function buildSimpleDuck(B, scene) {
    const parts = [];
    const mat = (hex) => { const m = gooseMaterial(B, scene, 'gooseMod_duck_' + hex); m.diffuseColor = B.Color3.FromHexString(hex); return m; };
    const add = (mesh, m, x, y, z) => { mesh.material = m; mesh.position.set(x, y, z); parts.push(mesh); };
    add(B.MeshBuilder.CreateSphere('d', { diameter: 0.8, segments: 8 }, scene), mat('#ffd23f'), 0, 0.4, 0);
    add(B.MeshBuilder.CreateSphere('d', { diameter: 0.5, segments: 6 }, scene), mat('#ffd23f'), 0, 0.85, 0.1);
    add(B.MeshBuilder.CreateBox('d', { width: 0.3, height: 0.08, depth: 0.25 }, scene), mat('#ff8c1a'), 0, 0.8, 0.4);
    const merged = B.Mesh.MergeMeshes(parts, true, true, undefined, false, true);
    merged.name = 'gooseMod_grenadeTemplate';
    return merged;
  }

  // Low-poly fallback goose made of basic shapes (used if "Simple" is picked or the
  // embedded model is missing).
  function buildSimpleGoose(B, scene) {
    const parts = [];
    const mat = (hex) => { const m = gooseMaterial(B, scene, 'gooseMod_' + hex); m.diffuseColor = B.Color3.FromHexString(hex); return m; };
    const C = CONFIG.gooseColors, body = mat(C.body), orange = mat(C.beak), black = mat(C.eyes);
    const add = (mesh, m, x, y, z, rx, sx, sy, sz) => {
      mesh.material = m; mesh.position.set(x, y, z); mesh.rotation.x = rx || 0;
      mesh.scaling.set(sx || 1, sy || 1, sz || 1); parts.push(mesh);
    };
    add(B.MeshBuilder.CreateSphere('g', { diameter: 0.8, segments: 8 }, scene), body, 0, 0.45, -0.05, 0, 0.85, 0.75, 1.3);
    add(B.MeshBuilder.CreateCylinder('g', { height: 0.6, diameterBottom: 0.2, diameterTop: 0.13, tessellation: 8 }, scene), body, 0, 0.9, 0.3, 0.25);
    add(B.MeshBuilder.CreateSphere('g', { diameter: 0.26, segments: 6 }, scene), body, 0, 1.22, 0.4, 0, 1, 1, 1.25);
    add(B.MeshBuilder.CreateCylinder('g', { height: 0.22, diameterBottom: 0.11, diameterTop: 0.05, tessellation: 6 }, scene), orange, 0, 1.2, 0.6, Math.PI / 2);
    add(B.MeshBuilder.CreateSphere('g', { diameter: 0.05, segments: 4 }, scene), black, -0.09, 1.26, 0.48);
    add(B.MeshBuilder.CreateSphere('g', { diameter: 0.05, segments: 4 }, scene), black, 0.09, 1.26, 0.48);
    for (const x of [-0.15, 0.15]) {
      add(B.MeshBuilder.CreateCylinder('g', { height: 0.22, diameter: 0.05, tessellation: 5 }, scene), orange, x, 0.1, 0);
      add(B.MeshBuilder.CreateBox('g', { width: 0.16, height: 0.03, depth: 0.2 }, scene), orange, x, 0.0, 0.06);
    }
    const merged = B.Mesh.MergeMeshes(parts, true, true, undefined, false, true);
    merged.name = 'gooseMod_template';
    return merged;
  }

  // "Goose gun": a goose-themed blaster laid along +Z, 1 unit long.
  function buildGooseGun(B, scene) {
    const parts = [];
    const mat = (hex) => { const m = gooseMaterial(B, scene, 'gooseMod_gun_' + hex); m.diffuseColor = B.Color3.FromHexString(hex); return m; };
    const C = CONFIG.gooseColors, white = mat(C.body), orange = mat(C.beak), black = mat(C.eyes);
    const add = (mesh, m, x, y, z, rx) => { mesh.material = m; mesh.position.set(x, y, z); mesh.rotation.x = rx || 0; parts.push(mesh); };
    add(B.MeshBuilder.CreateBox('gg', { width: 0.16, height: 0.18, depth: 0.6 }, scene), white, 0, 0, 0);                       // body
    add(B.MeshBuilder.CreateCylinder('gg', { height: 0.3, diameterBottom: 0.13, diameterTop: 0.04, tessellation: 8 }, scene), orange, 0, 0.01, 0.44, Math.PI / 2); // beak barrel
    add(B.MeshBuilder.CreateSphere('gg', { diameter: 0.04, segments: 4 }, scene), black, -0.08, 0.06, 0.24);                   // eyes
    add(B.MeshBuilder.CreateSphere('gg', { diameter: 0.04, segments: 4 }, scene), black, 0.08, 0.06, 0.24);
    add(B.MeshBuilder.CreateBox('gg', { width: 0.1, height: 0.22, depth: 0.1 }, scene), orange, 0, -0.17, -0.15, -0.3);         // webbed-foot grip
    add(B.MeshBuilder.CreateBox('gg', { width: 0.06, height: 0.06, depth: 0.26 }, scene), white, 0, 0.12, -0.05);                // sight / wing ridge
    const merged = B.Mesh.MergeMeshes(parts, true, true, undefined, false, true);
    merged.name = 'gooseMod_gunTemplate';
    return merged;
  }

  // ---------------------------------------------------------------------------------
  // Swapping logic
  // ---------------------------------------------------------------------------------
  let B = null, scene = null, gooseTpl = null, gunTpl = null, grenadeTpl = null;
  const players = new Map(); // player root -> { trigger, inst, hidden }
  const guns = new Map();    // gun mesh    -> { inst, hidden }
  const grenades = new Map(); // grenade mesh -> { inst, hidden }
  const origVisible = new WeakMap();

  const isOurs = (n) => /gooseMod_/.test(n.name || '') || (n.parent && /gooseMod_/.test(n.parent.name || ''));
  // If the game makes a new gun/grenade by cloning one we already swapped, the clone
  // inherits our model and the hidden state. Remove the copied model and un-hide it
  // first, so it is swapped (and later restored) like any other.
  function cleanClone(node) {
    const strays = node.getChildren ? node.getChildren((c) => /gooseMod_/.test(c.name || ''), true) : [];
    if (!strays.length) return;
    strays.forEach((c) => c.dispose());
    node.isVisible = true;
  }
  function labelOf(n) {
    const m = n.material, t = m && (m.diffuseTexture || m.albedoTexture);
    return [n.name, n.id, m && m.name, t && (t.name || t.url)].filter(Boolean).join(' ');
  }
  const isGrenade = (label) => CONFIG.grenadePattern.test(label);
  const isGun = (label) => CONFIG.facePattern.test(label) && CONFIG.gunWords.test(label) && !isGrenade(label);
  const isFace = (label) => CONFIG.facePattern.test(label) && !CONFIG.gunWords.test(label) && !isGrenade(label);

  function hide(meshes) {
    for (const m of meshes) {
      if (!origVisible.has(m)) origVisible.set(m, m.isVisible);
      m.isVisible = false;
    }
  }
  function restore(meshes) {
    for (const m of meshes) {
      if (m.isDisposed && m.isDisposed()) continue;
      if (origVisible.has(m)) { m.isVisible = origVisible.get(m); origVisible.delete(m); }
    }
  }

  function getGooseTemplate() {
    if (!gooseTpl) {
      gooseTpl = settings.model === 'detailed' && MODEL ? buildEmbedded(B, scene, MODEL, 'gooseMod_template') : buildSimpleGoose(B, scene);
      gooseTpl.isPickable = false;
      gooseTpl.setEnabled(false);
      log('goose template:', settings.model, 'triangles', gooseTpl.getTotalIndices() / 3);
    }
    return gooseTpl;
  }
  function getGrenadeTemplate() {
    if (!grenadeTpl) {
      grenadeTpl = GRENADE ? buildEmbedded(B, scene, GRENADE, 'gooseMod_grenadeTemplate') : buildSimpleDuck(B, scene);
      grenadeTpl.isPickable = false;
      grenadeTpl.setEnabled(false);
    }
    return grenadeTpl;
  }
  function getGunTemplate() {
    if (!gunTpl) { gunTpl = buildGooseGun(B, scene); gunTpl.isPickable = false; gunTpl.setEnabled(false); }
    return gunTpl;
  }

  function rootOf(node) { let n = node; while (n.parent) n = n.parent; return n; }
  function partOfGun(m, root) {
    for (let n = m; n && n !== root; n = n.parent) {
      const l = labelOf(n);
      if (CONFIG.gunWords.test(l) || isGrenade(l) || guns.has(n) || grenades.has(n)) return true;
    }
    return false;
  }

  function dressPlayer(trigger) {
    const root = rootOf(trigger);
    if (players.has(root)) return;
    const meshes = root.getChildMeshes ? root.getChildMeshes(false) : [];
    if (root.getTotalVertices) meshes.push(root);
    if (meshes.length > CONFIG.maxPlayerMeshes) { log('skipped: node tree too big to be one player', root.name, meshes.length); return; }
    // hide the egg body/face/hats, but never the player's gun (or anything attached to it)
    const hidden = meshes.filter((m) => !isOurs(m) && !partOfGun(m, root));
    hide(hidden);
    const inst = getGooseTemplate().clone('gooseMod_goose');
    inst.setEnabled(true);
    inst.parent = root;
    inst.scaling.setAll(CONFIG.gooseScale);
    inst.position.set(CONFIG.gooseOffset.x, CONFIG.gooseOffset.y, CONFIG.gooseOffset.z);
    inst.rotation.y = CONFIG.gooseRotationY;
    players.set(root, { trigger, inst, hidden });
    log('goose applied to', root.name);
  }

  function dressGun(gun) {
    if (guns.has(gun)) return;
    cleanClone(gun);
    const hidden = [gun].concat(gun.getChildMeshes ? gun.getChildMeshes(false).filter((m) => !isOurs(m)) : []);
    hide(hidden);
    const inst = getGunTemplate().clone('gooseMod_gun');
    inst.setEnabled(true);
    inst.parent = gun; // follows the gun's own movement / recoil
    let len = 1;
    try {
      gun.refreshBoundingInfo && gun.refreshBoundingInfo();
      const e = gun.getBoundingInfo().boundingBox.extendSize;
      len = 2 * Math.max(e.x, e.y, e.z) || 1;
      inst.position.copyFrom(gun.getBoundingInfo().boundingBox.center);
    } catch (e) { /* no bounds: keep defaults */ }
    inst.scaling.setAll(len * CONFIG.gunScale);
    inst.rotation.set(CONFIG.gunRotation.x, CONFIG.gunRotation.y, CONFIG.gunRotation.z);
    guns.set(gun, { inst, hidden });
    log('goose gun applied to', gun.name);
  }

  function dressGrenade(g) {
    if (grenades.has(g)) return;
    cleanClone(g);
    const hidden = [g].concat(g.getChildMeshes ? g.getChildMeshes(false).filter((m) => !isOurs(m)) : []);
    hide(hidden);
    const inst = getGrenadeTemplate().clone('gooseMod_grenade');
    inst.setEnabled(true);
    inst.parent = g; // flies, spins and bounces with the real grenade
    let size = 0.25;
    try {
      g.refreshBoundingInfo && g.refreshBoundingInfo();
      const bb = g.getBoundingInfo().boundingBox;
      size = 2 * Math.max(bb.extendSize.x, bb.extendSize.y, bb.extendSize.z) || size;
      inst.position.set(bb.center.x, bb.center.y - size / 2, bb.center.z);
    } catch (e) { /* no bounds: keep defaults */ }
    inst.scaling.setAll(size * 1.4 * CONFIG.grenadeScale);
    grenades.set(g, { inst, hidden });
    log('duck grenade applied to', g.name);
  }

  function undress(map, key) {
    const e = map.get(key);
    if (!e) return;
    restore(e.hidden);
    if (!e.inst.isDisposed()) e.inst.dispose();
    map.delete(key);
  }

  function resetAll(rebuildTemplates) {
    for (const k of [...players.keys()]) undress(players, k);
    for (const k of [...guns.keys()]) undress(guns, k);
    for (const k of [...grenades.keys()]) undress(grenades, k);
    if (rebuildTemplates) {
      if (gooseTpl) { gooseTpl.dispose(false, true); gooseTpl = null; }
      if (gunTpl) { gunTpl.dispose(false, true); gunTpl = null; }
    }
  }

  function scan() {
    const skinOn = settings.enabled && settings.gooseSkin;
    const gunsOn = settings.enabled && settings.gooseGuns;
    const ducksOn = settings.enabled && settings.duckGrenades;

    // drop swaps whose item is gone or whose toggle got switched off
    for (const [root, e] of players) {
      if (!skinOn || e.trigger.isDisposed() || root.isDisposed() || !e.trigger.isEnabled()) undress(players, root);
      else hide(e.hidden); // the game may re-show meshes on respawn
    }
    for (const [gun, e] of guns) {
      if (!gunsOn || gun.isDisposed()) undress(guns, gun);
      else hide(e.hidden);
    }
    for (const [g, e] of grenades) {
      if (!ducksOn || g.isDisposed()) undress(grenades, g);
      else hide(e.hidden);
    }
    if (!skinOn && !gunsOn && !ducksOn) return;
    for (const n of scene.meshes.concat(scene.transformNodes || [])) check(n);
  }

  // Decides what (if anything) to swap for one mesh. Also called the moment a new
  // mesh is added, so thrown grenades turn into ducks immediately.
  function check(n) {
    if (!settings.enabled || isOurs(n) || !n.isEnabled()) return;
    const label = labelOf(n);
    try {
      if (isGrenade(label)) { if (settings.duckGrenades && n.getTotalVertices) dressGrenade(n); return; }
      if (!CONFIG.facePattern.test(label)) return;
      if (settings.gooseGuns && isGun(label) && n.getTotalVertices) dressGun(n);
      else if (settings.gooseSkin && isFace(label)) dressPlayer(n);
    } catch (err) { console.warn('[GooseMod]', err); }
  }

  // ---------------------------------------------------------------------------------
  // Settings panel (Alt+G or the small "Goose Mod" button)
  // ---------------------------------------------------------------------------------
  function buildPanel() {
    const css = `
      #gooseModBtn{position:fixed;left:12px;bottom:12px;z-index:2147483646;font:600 12px/1 system-ui,sans-serif;
        background:#f4f2ec;color:#222;border:2px solid #f0912f;border-radius:16px;padding:7px 11px;cursor:pointer;opacity:.85}
      #gooseModBtn:hover{opacity:1}
      #gooseModPanel{position:fixed;left:12px;bottom:48px;z-index:2147483647;width:250px;display:none;
        font:13px/1.4 system-ui,sans-serif;background:#f4f2ec;color:#222;border:2px solid #f0912f;border-radius:12px;
        padding:12px 14px;box-shadow:0 6px 20px rgba(0,0,0,.25)}
      #gooseModPanel h3{margin:0 0 8px;font-size:14px}
      #gooseModPanel label{display:flex;gap:8px;align-items:center;margin:6px 0;cursor:pointer}
      #gooseModPanel select{margin-left:auto}
      #gooseModPanel small{display:block;margin-top:8px;color:#666}`;
    const style = document.createElement('style'); style.textContent = css; document.head.appendChild(style);

    const btn = document.createElement('button'); btn.id = 'gooseModBtn'; btn.textContent = 'Goose Mod';
    const panel = document.createElement('div'); panel.id = 'gooseModPanel';
    panel.innerHTML = `
      <h3>Goose Mod settings</h3>
      <label><input type="checkbox" data-k="enabled"> Mod enabled</label>
      <label><input type="checkbox" data-k="gooseSkin"> Goose skin on turkey-face eggs</label>
      <label><input type="checkbox" data-k="gooseGuns"> Goose guns on turkey gun skins</label>
      <label><input type="checkbox" data-k="duckGrenades"> Duck grenades (all grenades)</label>
      <label><input type="checkbox" data-k="grenadeSound"> Vine boom grenade sound*</label>
      <label>Goose model
        <select data-k="model"><option value="detailed">Detailed</option><option value="simple">Simple (fastest)</option></select></label>
      <label><input type="checkbox" data-k="debug"> Debug log (console)</label>
      <small>*Sound changes apply after reloading the page.<br>Alt+G opens/closes this panel. Saved in this browser only.</small>`;
    document.body.append(btn, panel);

    panel.querySelectorAll('[data-k]').forEach((el) => {
      const k = el.dataset.k;
      if (el.type === 'checkbox') el.checked = !!settings[k]; else el.value = settings[k];
      el.addEventListener('change', () => {
        settings[k] = el.type === 'checkbox' ? el.checked : el.value;
        save();
        if (scene) resetAll(k === 'model');
      });
      el.addEventListener('keydown', (e) => e.stopPropagation());
    });
    const toggle = () => { panel.style.display = panel.style.display === 'block' ? 'none' : 'block'; };
    btn.addEventListener('click', toggle);
    window.addEventListener('keydown', (e) => {
      if (e.altKey && (e.key === 'g' || e.key === 'G')) { e.preventDefault(); toggle(); }
    }, true);
  }
  installSoundSwap();
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', buildPanel); else buildPanel();

  // ---------------------------------------------------------------------------------
  // Wait for the game's Babylon scene, then start scanning
  // ---------------------------------------------------------------------------------
  const wait = setInterval(() => {
    const BAB = window.BABYLON;
    const s = BAB && BAB.Engine && BAB.Engine.LastCreatedScene;
    if (!s) return;
    clearInterval(wait);
    B = BAB; scene = s;
    scene.onNewMeshAddedObservable.add((m) => setTimeout(() => check(m), 0));
    log('scene found; scanning every', CONFIG.scanIntervalMs, 'ms');
    setInterval(scan, CONFIG.scanIntervalMs);
  }, 250);
})();
